-- Коллекции: floor = минимальная цена на продаже, avg = медиана 10 самых дешёвых лотов (Fragment, 2026-10-23)
on conflict (slug) do update set name=excluded.name, supply=excluded.supply, floor_ton=excluded.floor_ton, avg_ton=excluded.avg_ton,
  listings_sampled=excluded.listings_sampled, thumb=excluded.thumb, updated_at=excluded.updated_at;
